 12	@Service
 13	public class TransLogService {
 14	
 15	    private final String translogUrl;
 16	    private final RestClient restClient;
 17	
 18	    public TransLogService(
 19	            @Value("${translog.url}") String translogUrl,
 20	            @Value("${translog.timeout.seconds}") int timeoutSeconds) {
 21	        this.translogUrl = translogUrl;
 22	        this.restClient = RestClient.builder()
 23	                .baseUrl(translogUrl)
 24	                .build();
 25	    }
 26	
 27	    public QuoteResult getQuote(String zipCode, BigDecimal weightKg, String service) {
 28	        try {
 29	            int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
 30	
 31	            String url = String.format("/v2/quote?zip=%s&weight_g=%d&service=%s",
 32	                    zipCode, weightGrams, service);
 33	
 34	            TransLogResponse response = restClient.get()
 35	                    .uri(url)
 36	                    .retrieve()
 37	                    .body(TransLogResponse.class);
 38	
 39	            if (response == null) {
 40	                return QuoteResult.unavailable();
 41	            }
 42	
 43	            if (response.error != null) {
 44	                if ("ZIP_NOT_SERVED".equals(response.error)) {
 45	                    return QuoteResult.notServed();
 46	                }
 47	                return QuoteResult.unavailable();
 48	            }
 49	
 50	            if (response.priceCents == null || response.etaHours == null) {
 51	                return QuoteResult.unavailable();
 52	            }
 53	
 54	            BigDecimal price = new BigDecimal(response.priceCents)
 55	                    .divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
 56	
 57	            int days = (int) Math.ceil(response.etaHours / 24.0);
 58	
 59	            return QuoteResult.success(price, days);
 60	
 61	        } catch (Exception e) {
 62	            return QuoteResult.unavailable();
 63	        }
 64	    }
 65	
 66	    public static class QuoteResult {
 67	        private final boolean available;
 68	        private final boolean served;
 69	        private final BigDecimal price;
 70	        private final int days;
 71	
 72	        private QuoteResult(boolean available, boolean served, BigDecimal price, int days) {
 73	            this.available = available;
 74	            this.served = served;
 75	            this.price = price;
 76	            this.days = days;
 77	        }
 78	
 79	        public static QuoteResult success(BigDecimal price, int days) {
 80	            return new QuoteResult(true, true, price, days);
 81	        }
 82	
 83	        public static QuoteResult notServed() {
 84	            return new QuoteResult(true, false, null, 0);
 85	        }
 86	
 87	        public static QuoteResult unavailable() {
 88	            return new QuoteResult(false, false, null, 0);
 89	        }
 90	
 91	        public boolean isAvailable() {
 92	            return available;
 93	        }
 94	
 95	        public boolean isServed() {
 96	            return served;
 97	        }
 98	
 99	        public BigDecimal getPrice() {
100	            return price;
101	        }
102	
103	        public int getDays() {
104	            return days;
