253	    private BigDecimal calculateCouponDiscount(CheckoutRequest request,
254	                                                BigDecimal productsSubtotal,
255	                                                BigDecimal shippingCost,
256	                                                Map<String, Integer> itemQuantities) {
257	        if (request.getCoupon() == null) {
258	            return ZERO;
259	        }
260	
261	        BigDecimal discount = switch (request.getCoupon()) {
262	            case WELCOME10 -> {
263	                if (!isFirstPurchase(request.getCustomer().getCpf())) {
264	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
265	                }
266	                yield productsSubtotal.multiply(new BigDecimal("0.10"));
267	            }
268	            case MINUS50 -> {
269	                if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) {
270	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
271	                }
272	                yield new BigDecimal("50.00");
273	            }
274	            case FREESHIPPING -> {
275	                if (request.getShippingMethod() == ShippingMethod.STORE_PICKUP) {
276	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
277	                }
278	                yield shippingCost;
279	            }
280	            case BUY3PAY2 -> {
281	                BigDecimal buy3pay2Discount = ZERO;
282	                for (var entry : itemQuantities.entrySet()) {
283	                    if (entry.getValue() >= 3) {
284	                        Product product = productRepository.findById(entry.getKey()).orElseThrow();
285	                        int freeItems = entry.getValue() / 3;
286	                        buy3pay2Discount = buy3pay2Discount.add(
287	                                product.getPrice().multiply(new BigDecimal(freeItems)));
288	                    }
289	                }
290	                yield buy3pay2Discount;
291	            }
292	        };
293	
294	        discount = discount.setScale(2, RoundingMode.HALF_EVEN);
295	
296	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"))
297	                .setScale(2, RoundingMode.HALF_EVEN);
298	
299	        if (discount.compareTo(maxDiscount) > 0) {
300	            discount = maxDiscount;
301	        }
302	
303	        return discount;
304	    }
