312	    private BigDecimal calculateInsurance(Region region, BigDecimal productsSubtotal) {
313	        BigDecimal rate;
314	        BigDecimal limit;
315	
316	        switch (region) {
317	            case SOUTHEAST, SOUTH -> {
318	                rate = new BigDecimal("0.01");
319	                limit = null;
320	            }
321	            case MIDWEST -> {
322	                rate = new BigDecimal("0.015");
323	                limit = null;
324	            }
325	            case NORTH -> {
326	                rate = new BigDecimal("0.025");
327	                limit = new BigDecimal("30.00");
328	            }
329	            case NORTHEAST -> {
330	                rate = new BigDecimal("0.02");
331	                limit = new BigDecimal("30.00");
332	            }
333	            default -> {
334	                rate = ZERO;
335	                limit = null;
336	            }
337	        }
338	
339	        BigDecimal insurance = productsSubtotal.multiply(rate).setScale(2, RoundingMode.HALF_EVEN);
340	
341	        if (limit != null && insurance.compareTo(limit) > 0) {
342	            insurance = limit;
343	        }
344	
345	        return insurance;
346	    }
